import java.util.*;
interface NightService {double applyNightFare(double fare);}
abstract class Cab {double km;static final double MINIMUM_FARE=100.0;Cab(double km){this.km=km;}abstract double getRate();abstract String getType();double calculateFare(boolean night){double fare=Math.max(km*getRate(),MINIMUM_FARE);if(night&&this instanceof NightService)fare=((NightService)this).applyNightFare(fare);return fare;}boolean supportsNightService(){return this instanceof NightService;}}
class Mini extends Cab {Mini(double km){super(km);}double getRate(){return 10.0;}String getType(){return "MINI";}}
class Sedan extends Cab implements NightService {Sedan(double km){super(km);}double getRate(){return 14.0;}public double applyNightFare(double f){return f*1.20;}String getType(){return "SEDAN";}}
class SUV extends Cab implements NightService {SUV(double km){super(km);}double getRate(){return 18.0;}public double applyNightFare(double f){return f*1.20;}String getType(){return "SUV";}}
public class CityCabFareMeter {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double total=0;for(int i=0;i<n;i++){String type=sc.next();double km=sc.nextDouble();String time=sc.next();Cab cab;switch(type){case "MINI":cab=new Mini(km);break;case "SEDAN":cab=new Sedan(km);break;default:cab=new SUV(km);}boolean night=time.equals("NIGHT");if(night&&!cab.supportsNightService())System.out.println(cab.getType()+": night service not available");else{double fare=cab.calculateFare(night);System.out.printf("%s: %.2f%n",cab.getType(),fare);total+=fare;}}System.out.printf("Total: %.2f%n",total);sc.close();}}